 6. validate-graph-schema.py gate          (C11/IN1)
"""
import argparse, hashlib, json, os, re, shutil, subprocess, sys
from datetime import datetime, timezone
from pathlib import Path

PLUGIN = Path(__file__).resolve()
PLUGIN = Path("/Users/dm/dev/dev/個人開発/harness/plugins/dev-graph")
SECRET_RE = re.compile(r"(gh[pousr]_[A-Za-z0-9]{16,}|github_pat_[A-Za-z0-9_]{20,})")
NODE_ID_RE = re.compile(r"\b(PVT_[A-Za-z0-9]+|PVTI_[A-Za-z0-9]+|PVTF_[A-Za-z0-9]+|MDU6[A-Za-z0-9]+|I_kw[A-Za-z0-9]+|IC_kw[A-Za-z0-9]+|PR_kw[A-Za-z0-9]+)\b")
SECRET_KEYS = {"token", "access_token", "secret", "password", "authorization", "node_id",
               "project_id_node", "item_id", "field_id"}


def sha256_file(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def run(cmd, **kw):
    return subprocess.run(cmd, capture_output=True, text=True, **kw)


def resolve_context(repo_root: str):
    r = run([sys.executable, str(PLUGIN / "scripts" / "resolve-repo-context.py"),
             "--repo-root", repo_root, "--mode", "write"])
    if r.returncode != 0:
        raise SystemExit("C24 resolve-repo-context failed: " + r.stderr.strip())
    return json.loads(r.stdout)


def build_config(ctx, repo: Path, hook_source: str):
    name = repo.name
    prefix = re.sub(r"[^a-z0-9-]", "-", name.lower())
    prefix = re.sub(r"^[^a-z]+", "", prefix) or "dg"
    return {
        "schema_version": "1.0.0",
        "repository_id": ctx["repository_id"],
        "content_roots": {
            "issues": "issues", "tasks": "tasks", "specifications": "specs",
            "architecture": "architecture", "features": "features",
            "documents": "docs", "system_spec": "system-spec",
        },
        "local_state": {
            "graph": ".dev-graph/state/graph.json",
            "cache": ".dev-graph/cache",
            "locks": ".dev-graph/locks",
        },
        "github": {
            "enabled": False,
            "issue_repository": "local/" + re.sub(r"[^A-Za-z0-9_.-]", "-", name),
            "projects": [{
                "alias": "delivery", "owner_type": "user", "owner_login": "local",
                "project_number": 1, "default": True,
                "auto_add": {"artifact_kinds": ["task"], "confirmation_status": "confirmed",
                             "evaluation_status": "pass", "implementation_readiness": "complete"},
                "field_mappings": [
                    {"local_field": "status", "project_field_name": "Status",
                     "value_type": "single_select", "direction": "local_to_project",
                     "option_map": {"active": "In Progress", "blocked": "Blocked", "done": "Done"}},
                    {"local_field": "priority", "project_field_name": "Priority",
                     "value_type": "single_select", "direction": "bidirectional",
