                ],
            }],
            "completion_policy": {
                "trigger": "linked_pr_merged", "required_pull_requests": "all",
                "target_branch": "default", "closed_unmerged": "keep_active",
                "issue_reopened": "reopen_task",
                "revert": "create_follow_up_unless_issue_reopened",
                "local_reconciliation": ["manual_sync", "claude_hook", "scheduled_sync"],
                "scheduled_reconciliation": {"enabled": True, "interval_minutes": 5,
                                             "owner": "claude_session_start",
                                             "entry_point": "dev-graph sync --reconcile-lifecycle"},
            },
        },
        "execution_tracker": {"mode": "beads",
                              "beads": {"issue_prefix": prefix, "server_mode": False,
                                        "github_mirror": "bd_github_push_only",
                                        "board": "static-render"}},
        "worktrees": {"enabled": True, "lease_ttl_seconds": 1800, "heartbeat_seconds": 60,
                      "coordination_store": "git_common_dir",
                      "completion_write_branch": "default",
                      "dirty_worktree_policy": "fail_closed"},
        "claude_hooks": {"source": hook_source if hook_source in ("plugin", "project", "disabled") else "plugin",
                         "project_plugin_link": ".claude/dev-graph-plugin",
                         "session_start": True, "post_tool_reconcile": True,
