        "path_policy": {"authority": "caller-repository", "stored_paths": "repository-relative",
                        "allow_outside_repository": False,
                        "follow_content_symlinks_outside_repository": False},
    }


def hygiene(cfg, repo: Path):
    findings = []

    def walk(node, path):
        if isinstance(node, dict):
            for k, v in node.items():
                if k.lower() in SECRET_KEYS:
                    findings.append({"path": f"{path}.{k}", "reason": "forbidden_key"})
                walk(v, f"{path}.{k}")
        elif isinstance(node, list):
            for i, v in enumerate(node):
                walk(v, f"{path}[{i}]")
        elif isinstance(node, str):
            if node.startswith("/") or node.startswith("~") or re.match(r"^[A-Za-z]:[\\/]", node):
                findings.append({"path": path, "reason": "absolute_path"})
            if str(repo) in node:
                findings.append({"path": path, "reason": "host_absolute_path_fragment"})
            if SECRET_RE.search(node):
                findings.append({"path": path, "reason": "token_like_value"})
            if NODE_ID_RE.search(node):
                findings.append({"path": path, "reason": "github_node_id"})
    walk(cfg, "$")
    return findings


def plan(repo: Path, cfg_obj):
    """Return (planned, preserved, templates_report, migration_preview)."""
    planned, preserved = [], []
    dg = repo / ".dev-graph"
    for rel in ["issues", "tasks", "specs", "architecture", "features", "docs", "system-spec"]:
        p = repo / rel
        (preserved if p.is_dir() else planned).append(
            f"dir:{rel}" if p.is_dir() else {"action": "create_dir", "path": rel})
    for rel in [".dev-graph", ".dev-graph/state", ".dev-graph/cache", ".dev-graph/locks",
                ".dev-graph/templates"]:
        p = repo / rel
        (preserved if p.is_dir() else planned).append(
            f"dir:{rel}" if p.is_dir() else {"action": "create_dir", "path": rel})
    cfg = dg / "config.json"
    if cfg.exists():
        preserved.append("file:.dev-graph/config.json")
    else:
        planned.append({"action": "create_file", "path": ".dev-graph/config.json"})
    graph = dg / "state" / "graph.json"
    if graph.exists():
        preserved.append("file:.dev-graph/state/graph.json")
    else:
        planned.append({"action": "create_file", "path": ".dev-graph/state/graph.json"})
    link = dg / "graph.json"
    if link.is_symlink() or link.exists():
        preserved.append("symlink:.dev-graph/graph.json")
    else:
        planned.append({"action": "create_symlink", "path": ".dev-graph/graph.json",
                        "target": "state/graph.json"})

    tpl_src = PLUGIN / "templates"
    tpl_dst = dg / "templates"
    created, kept, edited, migration = [], [], [], []
    for src in sorted(tpl_src.iterdir()):
        if not src.is_file():
            continue
        dst = tpl_dst / src.name
        if not dst.exists():
            planned.append({"action": "create_file", "path": f".dev-graph/templates/{src.name}"})
            created.append(src.name)
        else:
            if sha256_file(dst) == sha256_file(src):
                kept.append(src.name)
                preserved.append(f"template:{src.name}")
            else:
                edited.append(src.name)
                migration.append({"path": f".dev-graph/templates/{src.name}",
                                  "reason": "user_edited",
                                  "existing_digest": sha256_file(dst),
                                  "plugin_default_digest": sha256_file(src)})
    # contract asset coverage
    contract = json.loads((tpl_src / "template-contract.json").read_text(encoding="utf-8"))
    required = {contract["common_frontmatter"]["template"], "template-contract.json",
                contract["graph_projection"]["template"]}
    for art in contract["artifacts"].values():
        required.add(art["template"])
        for v in art.get("subtype_templates", {}).values():
            required.add(v)
        for v in art.get("conditional_templates", {}).values():
            required.add(v)
    if contract["system_plan"].get("task_overlay"):
        required.add(contract["system_plan"]["task_overlay"])
    missing_contract = sorted(n for n in required
                              if not (tpl_dst / n).exists() and n not in created)
    templates = {"total_plugin_templates": len([p for p in tpl_src.iterdir() if p.is_file()]),
                 "created": sorted(created), "preserved": sorted(kept),
                 "user_edited": sorted(edited),
                 "missing_contract_assets": missing_contract,
                 "contract_required": sorted(required)}
    return planned, sorted(preserved), templates, migration


def apply_plan(repo: Path, planned, cfg_obj):
    for ch in planned:
        target = repo / ch["path"]
        assert os.path.realpath(target.parent if not target.exists() else target).startswith(
            os.path.realpath(repo)), "containment violation"
        if ch["action"] == "create_dir":
            target.mkdir(parents=True, exist_ok=True)
        elif ch["action"] == "create_symlink":
            target.symlink_to(ch["target"])
        elif ch["action"] == "create_file":
            target.parent.mkdir(parents=True, exist_ok=True)
            if ch["path"] == ".dev-graph/config.json":
                target.write_text(json.dumps(cfg_obj, ensure_ascii=False, indent=2,
                                             sort_keys=True) + "\n", encoding="utf-8")
                os.chmod(target, 0o600)
            elif ch["path"] == ".dev-graph/state/graph.json":
                target.write_text(json.dumps(
                    {"schema_version": "1.0.0", "graph_revision": 0, "nodes": []},
                    ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
                os.chmod(target, 0o600)
            elif ch["path"].startswith(".dev-graph/templates/"):
                shutil.copyfile(PLUGIN / "templates" / Path(ch["path"]).name, target)


def hook_report(repo: Path, requested: str, ctx):
    manifest = PLUGIN / "hooks" / "hooks.json"
    events = []
    if manifest.exists():
        events = sorted(json.loads(manifest.read_text(encoding="utf-8"))["hooks"].keys())
    settings = repo / ".claude" / "settings.json"
    proj_events, doubles = [], []
    settings_present = settings.exists()
    if settings_present:
        try:
            s = json.loads(settings.read_text(encoding="utf-8"))
        except Exception:
            s = {}
        for ev, groups in (s.get("hooks") or {}).items():
            for g in groups or []:
                for h in g.get("hooks", []):
                    if "dev-graph" in json.dumps(h):
                        proj_events.append(ev)
                        if ev in events:
                            doubles.append(f".claude/settings.json#hooks.{ev}")
    diagnostics = []
    for extra in [".claude/settings.local.json"]:
        if (repo / extra).exists():
            diagnostics.append(f"{extra}_present_may_override_effective_hooks")
    effective = "plugin" if events else ("project" if proj_events else "disabled")
    rejected = None
    if requested == "project-fallback" and events:
        rejected = ("effective plugin hook manifest is present; project-fallback is only allowed "
                    "for plain-symlink installs without an effective plugin hook")
    elif requested == "plugin" and events:
        rejected = ("effective plugin hook manifest is present; project-fallback is only allowed "
                    "for plain-symlink installs without an effective plugin hook")
    return {"requested_source": requested, "effective_source": effective,
            "plugin_hook_manifest": "hooks/hooks.json" if events else None,
            "plugin_hook_events": events,
            "project_settings_present": settings_present,
            "project_dev_graph_hook_events": sorted(set(proj_events)),
            "project_fallback_applied": False,
            "project_fallback_rejected_reason": rejected,
            "double_registration_paths": sorted(set(doubles)),
            "settings_write_count": 0, "rollback_manifest": None,
            "diagnostics": diagnostics}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo-root", required=True)
    ap.add_argument("--hook-source", default="plugin")
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--receipt-out", default=None)
    a = ap.parse_args()

    ctx = resolve_context(a.repo_root)
    repo = Path(ctx["repo_root"])
    if os.path.realpath(repo) != os.path.realpath(ctx["content_roots"]["repository"]):
        raise SystemExit("fail-closed: repo_root/content root realpath mismatch")
    if os.path.realpath(repo) != os.path.realpath(a.repo_root):
        raise SystemExit("fail-closed: requested root not identical to resolved root")

    failures = []
    cfg_path = repo / ".dev-graph" / "config.json"
    cfg_obj = (json.loads(cfg_path.read_text(encoding="utf-8")) if cfg_path.exists()
