    cfg_obj = json.loads(cfg_path.read_text(encoding="utf-8")) if cfg_path.exists() else cfg_obj
    schema = json.loads((PLUGIN / "schemas" / "repo-config.schema.json").read_text(encoding="utf-8"))
    cfg_errors = []
    try:
        import jsonschema
