    except ImportError:
        cfg_errors = ["jsonschema_unavailable"]
    if cfg_obj.get("repository_id") != ctx["repository_id"]:
        cfg_errors.append("repository_id mismatch with C24 receipt")
    if cfg_obj.get("claude_hooks", {}).get("source") != ("plugin" if a.hook_source == "plugin" else cfg_obj.get("claude_hooks", {}).get("source")):
        cfg_errors.append("claude_hooks.source mismatch with requested hook source")

    findings = hygiene(cfg_obj, repo)

    graph_path = repo / cfg_obj["local_state"]["graph"]
    vr = run([sys.executable, str(PLUGIN / "scripts" / "validate-graph-schema.py"),
              "--graph", str(graph_path), "--repo-root", str(repo)])
